from typing import List

class Solution:
    def findMinArrowShots(self, points: List[List[int]]) -> int:
        points.sort(key=lambda p: p[1])
        arrows = 0
        arrow_x = None

        for start, end in points:
            if arrow_x is None or start > arrow_x:
                arrows += 1
                arrow_x = end
        return arrows

